def split_cents(total, people):
    if isinstance(total, bool) or not isinstance(total, int) or total < 0:
        raise ValueError("total must be a non-negative integer")
    if isinstance(people, bool) or not isinstance(people, int) or people <= 0:
        raise ValueError("people must be a positive integer")
    base, remainder = divmod(total, people)
    return [base + (1 if i < remainder else 0) for i in range(people)]

