def merge_intervals(intervals):
    if not isinstance(intervals, (list, tuple)):
        raise ValueError('Expected a list or tuple of integer intervals')
    for pair in intervals:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise ValueError('Each interval needs two endpoints')
        start, end = pair
        if not isinstance(start, int) or isinstance(start, bool) or not isinstance(end, int) or isinstance(end, bool) or start > end:
            raise ValueError('Expected ordered integer endpoints')
    merged = []
    for start, end in sorted((start, end) for start, end in intervals):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged = merged + [(start, end)]
    return merged

